def histogram(test):
    # Split the string into words
    words = test.split()

    # Create an empty dictionary to store letter counts
    count_dict = {}

    for word in words:
        if word not in count_dict:
            count_dict[word] = 1  # If a new word, set the count as 1
        else:
            count_dict[word] += 1  # If an existing word, increment the count by 1

    # Find the maximum count
    max_count = max(count_dict.values(), default=0) if count_dict else 0

    # Return a dictionary containing only words with the maximum count
    return {k: v for k, v in count_dict.items() if v == max_count}
```

