def do_algebra(operator, operand):
    # Initialize the result to be the first number in the operand list
    result = operand[0]

    # Iterate over each operator and its corresponding operand
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]

    return result
```
