def count_nums(arr):
    def sum_digits(n):
        """Helper function to calculate the sum of digits"""
        if n < 0:
            return -1 * sum([int(i) for i in str(-1*n)[1:]])  # Sum of signed digits excluding first digit
        else:
            return sum([int(i) for i in str(n)])

    count = 0
    for num in arr:
        if sum_digits(num) > 0:
            count += 1

    return count
```

